defmodule Jamdb.Oracle.Integration.ReturningTest do
  use ExUnit.Case, async: false

  @moduletag :oracle

  alias Jamdb.Oracle.Integration
  alias Jamdb.Oracle.Integration.Repo

  defmodule Item do
    use Ecto.Schema

    schema "jamdb_it_returning" do
      field :name, :string
      field :qty, :integer
    end
  end

  setup_all do
    start_supervised!({Repo, Integration.config()})
    Integration.drop_table(Repo, "jamdb_it_returning")

    Repo.query!(
      "CREATE TABLE jamdb_it_returning (id INTEGER GENERATED BY DEFAULT AS IDENTITY " <>
        "PRIMARY KEY, name VARCHAR2(20), qty INTEGER)"
    )

    on_exit(fn ->
      Integration.with_repo(Repo, fn ->
        Integration.drop_table(Repo, "jamdb_it_returning")
      end)
    end)

    :ok
  end

  test "insert, update and delete return several fields" do
    {:ok, item} = Repo.insert(%Item{name: "a", qty: 1}, returning: [:id, :name, :qty])
    assert %Item{id: id, name: "a", qty: 1} = item
    assert is_integer(id)

    {:ok, item} =
      item |> Ecto.Changeset.change(qty: 2) |> Repo.update(returning: [:name, :qty])

    assert %Item{id: ^id, name: "a", qty: 2} = item

    assert {:ok, %Item{name: "a", qty: 2}} = Repo.delete(item, returning: [:name, :qty])
    assert Repo.get(Item, id) == nil
  end

  test "raw queries with out binds keep one list per bind" do
    Repo.insert!(%Item{name: "b", qty: 5})

    assert %{rows: [[_id], [5]]} =
             Repo.query!(
               "UPDATE jamdb_it_returning SET qty = qty WHERE name = 'b' RETURN id, qty INTO :id, :qty",
               [],
               out: [:integer, :integer]
             )
  end
end
